mapper.sql:
run_id != ''
and session_id != '' and session_id != 'unknown'
and started_at >= #{filter.startTime} and started_at < #{filter.endTime}

    and (positionCaseInsensitiveUTF8(user_id, #{filter.userKeyword}) > 0
         or positionCaseInsensitiveUTF8(username, #{filter.userKeyword}) > 0)

and organization = #{filter.organization}



            and (complete = 0 or dropped_count > 0 or pending_chunks > 0)

        and (status = #{filter.status} or archive_status = #{filter.status})


and trace_id = #{filter.traceId}
and run_id = #{filter.runId}
and agent_id = #{filter.agentId}

    and trace_id in (
        select trace_id from analytics_trace_spans final where 1 = 1

            and capability_kind = 'SKILL' and capability_name = #{filter.skill}


            and capability_kind = 'TOOL' and capability_name = #{filter.tool}

    )

mapper.select:
select  from analytics_trace_catalog final
where 
order by started_at desc, trace_id limit #{limit} offset #{offset}
